// Strip HTML, extract clean text, build OpenAI prompt
const html = $input.first().json.body || $input.first().json.data || '';

const siteText = html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 5000);

const form = $('Form: Параметры').first().json;
const duration = Number(form['Длительность (сек)']) || 60;
const wordCount = Math.round(duration * 2.3);
const lang = form['Язык'] || 'Русский';

const systemPrompt = `Ты — профессиональный сценарист для AI-видео аватаров. 
Пишешь живые, разговорные сценарии без канцелярита. 
Только чистый текст для зачитывания — никаких ремарок, скобок, таймкодов.`;

const userPrompt = `Вот текст с сайта:\n---\n${siteText}\n---\n
Задание: напиши сценарий для AI-аватара по имени ${form['Имя аватара']}.
Тема: ${form['Тема / продукт']}
Длительность: ${duration} сек (~${wordCount} слов)
Язык: ${lang}

Требования:
- Разговорный стиль, первое лицо
- Конкретные факты и детали с сайта
- Чёткий призыв к действию в финале
- Только текст — никаких заголовков или пояснений`;

return [{
  json: {
    avatar_name: form['Имя аватара'],
    topic: form['Тема / продукт'],
    duration_sec: duration,
    word_count_target: wordCount,
    language: lang,
    system_prompt: systemPrompt,
    user_prompt: userPrompt
  }
}];

const openaiResp = $input.first().json;
const meta = $('Code: Подготовить промпт').first().json;

const script = openaiResp.choices[0].message.content.trim();
const words = script.split(/\s+/).length;
const estimatedSec = Math.round(words / 2.3);

return [{
  json: {
    script,
    avatar_name: meta.avatar_name,
    topic: meta.topic,
    language: meta.language,
    word_count: words,
    estimated_duration_sec: estimatedSec,
    tokens_used: openaiResp.usage?.total_tokens || 0,
    model: openaiResp.model
  }
}];
